    "sentences": [
      {
        "term": "Καὶ αὕτη ἐστὶν ἡ μαρτυρία τοῦ Ἰωάννου·",
        "transliteration": "Kai hautē estin hē martyria tou Iōannou:",
        "translations": [
          "E este é o testemunho de João"
        ],
        "type": "Frase"
      },
      {
        "term": "Οὐκ εἰμὶ ἐγὼ ὁ Χριστός.",
        "transliteration": "Ouk eimi egō ho Christos.",
        "translations": [
          "Eu não sou o Cristo",
          "Não sou eu o Cristo"
        ],
        "type": "Frase"
      },
      {
        "term": "Καὶ ἠρώτησαν αὐτόν· Τί οὖν;",
        "transliteration": "Kai ērōtēsan auton: Ti oun?",
        "translations": [
          "E perguntaram a ele: O que então?"
        ],
        "type": "Frase"
      },
      {
        "term": "Ἠλίας εἶ σύ; Καὶ λέγει· Οὐκ εἰμί.",
        "transliteration": "Hēlias ei sy? Kai legei: Ouk eimi.",
        "translations": [
          "Elias és tu? E diz: Não sou",
          "Tu és Elias? E diz: Não sou"
        ],
        "type": "Frase"
      },
      {
        "term": "Ὁ προφήτης εἶ σύ; Οὔ.",
        "transliteration": "Ho prophētēs ei sy? Ou.",
        "translations": [
          "O profeta és tu? Não",
          "Tu és o profeta? Não"
        ],
        "type": "Frase"
      },
      {
        "term": "Ὑμεῖς ἐκ τοῦ Θεοῦ ἐστέ, τεκνία",
        "transliteration": "Hymeis ek tou Theou este, teknia",
        "translations": [
          "Vocês são de Deus, filhinhos"
        ],
        "type": "Frase"
      },
      {
        "term": "Αὐτοὶ ἐκ τοῦ κόσμου εἰσίν",
        "transliteration": "Autoi ek tou kosmou eisin",
        "translations": [
          "Eles são do mundo"
        ],
        "type": "Frase"
      },
      {
        "term": "Ἡμεῖς ἐκ τοῦ Θεοῦ ἐσμεν.",
        "transliteration": "Hēmeis ek tou Theou esmen.",
        "translations": [
          "Nós somos de Deus"
        ],
        "type": "Frase"
      },
      {
        "term": "Τὰ πρόβατα τὰ ἐμὰ τῆς φωνῆς μου ἀκούουσιν,",
        "transliteration": "Ta probata ta ema tēs phōnēs mou akouousin,",
        "translations": [
          "As minhas ovelhas ouvem a minha voz"
        ],
        "type": "Frase"
      },
      {
        "term": "κἀγὼ γινώσκω αὐτὰ καὶ ἀκολουθοῦσίν μοι·",
        "transliteration": "kagō ginōskō auta kai akolouthousin moi:",
        "translations": [
          "e eu as conheço e elas me seguem"
        ],
        "type": "Frase"
      },
      {
        "term": "κἀγὼ δίδωμι αὐτοῖς ζωὴν αἰώνιον,",
        "transliteration": "kagō didōmi autois zōēn aiōnion,",
        "translations": [
          "e eu lhes dou vida eterna"
        ],
        "type": "Frase"
      },
      {
        "term": "καὶ οὐ μὴ ἀπόλωνται εἰς τὸν αἰῶνα",
        "transliteration": "kai ou mē apolōntai eis ton aiōna",
        "translations": [
          "e elas jamais perecerão"
        ],
        "type": "Frase"
      },
      {
        "term": "καὶ οὐχ ἁρπάσει τις αὐτὰ ἐκ τῆς χειρός μου.",
        "transliteration": "kai ouch harpasei tis auta ek tēs cheiros mou.",
        "translations": [
          "e ninguém as arrancará da minha mão"
        ],
        "type": "Frase"
      }
    ],
