    "sentences": [
      {
        "term": "Καὶ περιῆγεν ὁ Ἰησοῦς τὰς πόλεις πάσας καὶ τὰς κώμας, διδάσκων ἐν ταῖς συναγωγαῖς αὐτῶν καὶ κηρύσσων τὸ εὐαγγέλιον τῆς βασιλείας καὶ θεραπεύων πᾶσαν νόσον καὶ πᾶσαν μαλακίαν ἐν τῷ λαῷ.",
        "transliteration": "Kai periēgen ho Iēsous tas poleis pasas kai tas kōmas, didaskōn en tais synagōgais autōn kai kēryssōn to euangelion tēs basileias kai therapeuōn pasan noson kai pasan malakian en tō laō.",
        "translations": [
          "E percorria Jesus todas as cidades e os povoados, ensinando nas sinagogas deles e pregando o evangelho do reino e curando toda enfermidade e toda fraqueza no povo."
        ],
        "type": "Frase"
      },
      {
        "term": "Καὶ προσελθὼν ὁ Ἰησοῦς ἐλάλησεν αὐτοῖς λέγων· Ἐδόθη μοι πᾶσα ἐξουσία ἐν οὐρανῷ καὶ ἐπὶ γῆς.",
        "transliteration": "Kai proselthōn ho Iēsous elalēsen autois legōn: Edothē moi pasa exousia en ouranō kai epi gēs.",
        "translations": [
          "E aproximando-se Jesus lhes falou dizendo: Foi-me dada toda autoridade no céu e sobre a terra."
        ],
        "type": "Frase"
      },
      {
        "term": "Πορευθέντες μαθητεύσατε πάντα τὰ ἔθνη, βαπτίζοντες αὐτοὺς εἰς τὸ ὄνομα τοῦ πατρὸς καὶ τοῦ υἱοῦ καὶ τοῦ Ἁγίου Πνεύματος,",
        "transliteration": "Poreuthentes mathēteusate panta ta ethnē, baptizontes autous eis to onoma tou patros kai tou huiou kai tou Hagiou Pneumatos,",
        "translations": [
          "Indo, façam discípulos de todas as nações, batizando-os no nome do Pai e do Filho e do Espírito Santo,"
        ],
        "type": "Frase"
      },
      {
        "term": "διδάσκοντες αὐτοὺς τηρεῖν πάντα ὅσα ἐνετειλάμην ὑμῖν· καὶ ἰδού, ἐγὼ μεθ᾽ ὑμῶν εἰμι πάσας τὰς ἡμέρας ἕως τῆς συντελείας τοῦ αἰῶνος. Ἀμήν.",
        "transliteration": "didaskontes autous tērein panta hosa eneteilamēn hymin; kai idou, egō meth’ hymōn eimi pasas tas hēmeras heōs tēs synteleias tou aiōnos. Amēn.",
        "translations": [
          "ensinando-os a guardar tudo o que vos mandei; e eis que eu estou com vocês todos os dias até o fim dos tempos. Amém."
        ],
        "type": "Frase"
      },
      {
        "term": "ἐνεδυναμώθη τῇ πίστει, δοὺς δόξαν τῷ Θεῷ...",
        "transliteration": "enedynamōthē tē pistei, dous doxan tō Theō...",
        "translations": [
          "foi fortalecido na sua fé, dando glória a Deus..."
        ],
        "type": "Frase"
      }
    ],
